bool lv5e_segment_settings_init(lv5e_segment_settings_t *s, size_t index) {
  switch (index) {
    case 240:
      *s = SEG_240;
      return true;
    case 480:
      *s = SEG_480;
      return true;
    case 481:
      *s = SEG_481;
      return true;
    case 482:
      *s = SEG_482;
      return true;
    case 960:
      *s = SEG_960;
      return true;
    case 1920:
      *s = SEG_1920;
      return true;
    default:
      return false;
  }
}

/* ---------------- header ---------------- */

static const uint16_t HEADER_INFO_MAX[6] = {0x3ff, 0xc00, 0x1000, 0x2000, 0x4000, 0x8000};
static const int32_t HEADER_INFO_OFFSETS[6] = {0, 10, 12, 13, 14, 15};

void lv5e_header_set_info(lv5e_header_t *h, unsigned index, int32_t value) {
  h->info = (uint16_t)(((int32_t)h->info & ~(int32_t)HEADER_INFO_MAX[index]) |
                       (value << HEADER_INFO_OFFSETS[index]));
}

int32_t lv5e_header_get_info(const lv5e_header_t *h, unsigned index) {
  return ((int32_t)h->info & (int32_t)HEADER_INFO_MAX[index]) >>
         HEADER_INFO_OFFSETS[index];
}

int32_t lv5e_enc_process_header(lv5e_header_t *hdr, int32_t ch,
                                int32_t *enc_frm_len_usable, uint8_t *encoded_frame) {
  int32_t hdr_size = 0;
  (void)ch;
  *enc_frm_len_usable = hdr->enc_frm_len_provided;
  lv5e_header_set_info(hdr, LV5E_ENC_SIZE_INDEX, *enc_frm_len_usable);
  encoded_frame[0] = (uint8_t)(hdr->info & 0xff);
  encoded_frame[1] = (uint8_t)(hdr->info >> 8);
  hdr_size += 2;
  return hdr_size;
}

void lv5e_enc_get_encoded_frame_size(int32_t *encoded_frame_size, lv5e_enc_context_t *ctx) {
  int32_t extra_bytes = 0;
  int32_t enc_frm_len_provided = ctx->hdr_s.enc_frm_len_provided;
  lv5e_fdata_all_buffer_t *ecb = &ctx->ebuffer;
  extra_bytes += 2;
  *encoded_frame_size = extra_bytes + ecb->ch_num * enc_frm_len_provided;
}
